let movedRed = 0;
let movedBlack = 0;
for (let y = 0; y < 128; y++) {
  for (let x = 0; x < 128; x++) {
    if (after[y][x] === lattice[y][x]) continue;
    if ((x + y) % 2 === 0) movedRed++;
    else movedBlack++;
  }
}
console.log('red cells that flipped:', movedRed, 'of 8192');
console.log('black cells that flipped:', movedBlack, '(must be 0)');
