let acc = await black();
for (let f = 0; f < FRAMES; f++) {
  const sample = await trace(f, spp);
  acc = await accumulate(acc, sample, f);
  await paint(acc);
  render(paint.canvas);
}

console.log('total samples per pixel:', FRAMES * spp);
